  onboarding: AppOnboarding('FinTrack Pro க்கு வரவேற்கிறோம்', 'உங்கள் AI இயங்கும் நிதி கட்டளை மையம். தெளிவுடன் உங்கள் பணத்தை கண்காணிக்கவும், பட்ஜெட் செய்யவும், வளர்க்கவும்.', 'உங்கள் பணத்தை தெளிவாகக் காண்க', 'அனைத்து கணக்குகளிலும் அழகிய பகுப்பாய்வு, ஸ்மார்ட் பட்ஜெட்கள் மற்றும் நிகழ் நேர நுண்ணறிவுகள்.', 'உங்கள் தனிப்பட்ட AI பயிற்சியாளர்', 'தனிப்பயன் பரிந்துரைகள், செலவு கணிப்புகள் மற்றும் நிதி ஆரோக்கிய மதிப்பீட்டைப் பெறுங்கள்.', 'வங்கி தர பாதுகாப்பு', 'மறையாக்கப்பட்ட, தனிப்பட்ட மற்றும் நிறுவன கட்டமைப்புடன் கட்டப்பட்டது. உங்கள் தரவு உங்களுக்கே சொந்தம்.'),
  messages: AppMessages('பூஜ்யத்தை விட அதிகமான தொகையை உள்ளிடவும்', 'ஒரு பிரிவைத் தேர்ந்தெடுக்கவும்', 'பரிவர்த்தனை புதுப்பிக்கப்பட்டது', 'பரிவர்த்தனை நீக்கப்பட்டது', 'குறிப்பு நீக்கப்பட்டது', 'குறிப்பு புதுப்பிக்கப்பட்டது', 'குறிப்பு உருவாக்கப்பட்டது', 'தலைப்பில்லாத', 'சந்தா நீக்கப்பட்டது', 'பெயர் மற்றும் சரியான தொகையை உள்ளிடவும்', 'சந்தா சேர்க்கப்பட்டது', 'பரிவர்த்தனை பகுப்பாய்வு செய்யப்பட்டது ✨', 'சரியான தொகையை உள்ளிடவும்', 'AI கோரிக்கை தோல்வியடைந்தது', 'இந்த வரம்பில் பரிவர்த்தனைகள் இல்லை', 'அச்சு உரையாடல் திறக்கிறது — PDF ஆக சேமிக்கவும்', 'தயவுசெய்து ஒரு பட கோப்பை பதிவேற்றவும்', 'படம் மிகப்பெரியது (அதிகபட்சம் 8MB)', 'மாதிரி ரசீதை ஏற்ற முடியவில்லை', 'ரசீது ஸ்கேன் செய்யப்பட்டது ✨', 'சுயவிவரம் புதுப்பிக்கப்பட்டது', 'இலக்கு நீக்கப்பட்டது', 'இலக்கு பெயர் மற்றும் சரியான இலக்கை உள்ளிடவும்', 'தவறான காப்பு கோப்பு', 'காப்பு கோப்பிலிருந்து தரவு மீட்டமைக்கப்பட்டது', 'கோப்பை படிக்க முடியவில்லை', 'உரிமங்கள் திறக்கப்படுகிறது…', 'தரவு ஏற்றுமதி · JSON', 'காப்பு இறக்குமதி செய்யப்பட்டது', 'வாராந்திர சுருக்கம் உருவாக்கப்பட்டது', 'நெட்வொர்க் பிழை', 'சுருக்கத்தை உருவாக்க முடியவில்லை', 'காப்பு இறக்குமதி', 'JSON காப்பு கோப்பிலிருந்து தரவை மீட்டெடுக்கவும்', 'இறக்குமதி', 'உங்கள் தனிப்பட்ட விவரங்கள் மற்றும் விருப்பத்தேர்வுகளை புதுப்பிக்கவும்.', 'உங்கள் நிதி தரவை நிர்வகிக்கவும்', 'உங்கள் அனைத்து தரவையும் JSON ஆக பதிவிறக்கவும்', 'FinTrack ஐ அதன் அசல் நிலைக்கு மீட்டமைக்கவும்', 'உங்கள் கணக்கு மற்றும் தரவை நிரந்தரமாக நீக்கவும்', '{name} க்கு {amount} சேர்க்கப்பட்டது', 'ரசீதிலிருந்து {amount} செலவு பதிவு செய்யப்பட்டது', '{count} பரிவர்த்தனைகள் CSV க்கு ஏற்றுமதி செய்யப்பட்டன', '{key} எச்சரிக்கைகள் {state}', '{name} · {state}', 'ஒரு மின்னஞ்சல் முகவரியை உள்ளிடவும்', 'இயக்கத்தில்', 'அணை'),
  settingsDesc: AppSettingsDesc('FinTrack எப்படி தோற்றமளிக்கிறது என்பதை தனிப்பயனாக்கு', 'இருண்ட மற்றும் வெளிச்ச பயன்முறைக்கு இடையே மாறவும்', 'பிராந்திய மற்றும் காட்சி இயல்புநிலைகள்', 'செயலி இடைமுக மொழி', 'செயலியில் அனைத்து தொகைகளுக்கும் பயன்படுத்தப்படுகிறது', 'எந்த தாவல் முதலில் திறக்கிறது', 'நீங்கள் எதைப் பற்றி கேட்க விரும்புகிறீர்கள் என்பதைத் தேர்வுசெய்யவும்', 'பட்ஜெட் வரம்புகளை நெருங்கும்போது அறிவிக்கப்படுங்கள்', 'மீண்டும் நிகழும் பில்கள் கட்டணம் வசூலிப்பதற்கு முன் எச்சரிக்கை', 'வாராந்திர ஸ்மார்ட் பரிந்துரைகள்', 'ஒவ்வொரு திங்களன்றும் உங்கள் செலவின் சுருக்கம்', 'உங்கள் கணக்கைப் பாதுகாக்கவும்', 'திறக்க Face ID / கைரேகையைப் பயன்படுத்து', '4-இலக்க செயலி PIN', 'கணக்கு கடவுச்சொல்', 'செயலி தகவல் & சட்டப்பூர்வ', 'உங்கள் தரவை நாங்கள் எப்படி கையாள்கிறோம்', 'நுணுக்கமான அச்சு'),
  calcLabels: AppCalcLabels('கடன் விவரங்கள்', 'உடனடியாக மறுகணக்கீடு செய்ய உள்ளீடுகளை சரிசெய்யவும்', 'GST உள்ளீடுகள்', 'எந்த தொகையிலிருந்தும் GST சேர்க்கவும் அல்லது நீக்கவும்', 'சங்கிலி செயல்பாடுகள் · சதவீதம் · அடையாள மாற்றம்'),
  misc: AppMisc('ஏற்ற ஒரு ஜோடியை தட்டவும்', '6-மாத போக்கு', 'புதுப்பிப்பை தவறவிடாமல் உங்கள் மீண்டும் நிகழும் சந்தாக்களைச் சேர்க்கவும்.', 'முக்கியமானது நடக்கும்போது — பட்ஜெட் எச்சரிக்கைகள், AI நுண்ணறிவுகள், பில் நினைவூட்டல்கள் — அதை இங்கே பார்ப்பீர்கள்.', 'ஒரு இலக்கை அமைத்து முன்னேற்ற மைல்கற்களுடன் உங்கள் பணம் வளர்வதைப் பாருங்கள்.', 'பிரிவு உடைப்பைப் பார்க்க செலவுகளைச் சேர்க்கவும்.', 'மூல உடைப்பைப் பார்க்க வருவாயைச் சேர்க்கவும்.', 'உங்கள் குடும்ப கணக்கில் உள்ளவர்கள்', 'குடும்பம் முழுவதும் செலவுகளை கண்காணிக்கவும்', 'SIP / சேமிப்பு திட்டம்', 'உங்கள் கூட்டு வருமானத்தை திட்டமிடவும்'),
);
